package ru.neverland.townycompanies;

import java.nio.file.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;

/** SQLite worker never touches Bukkit. A work proof binds its first employer and exact rate. */
public final class CompanyPayrollStore implements AutoCloseable {
    public static final List<String> PROFESSIONS=List.of("blacksmith","farmer","engineer","guard","merchant","researcher","alchemist");
    public record Settings(UUID company,boolean enabled,long budget,Map<String,Long> rates,long revision){public Settings{Objects.requireNonNull(company);money(budget);rates=Map.copyOf(rates);if(revision<0||!PROFESSIONS.containsAll(rates.keySet()))throw new IllegalArgumentException("Некорректные ставки профессий");rates.values().forEach(CompanyPayrollStore::money);}public static Settings empty(UUID c){return new Settings(c,false,0,Map.of(),0);}}
    public record Work(UUID id,UUID company,UUID employee,String profession,int level,long cents,long created,String state){}
    private final ThreadPoolExecutor worker;private Connection db;private volatile boolean healthy,closed;
    private volatile Map<UUID,Settings> settings=Map.of();private volatile List<Work> outstanding=List.of();
    private static void money(long n){if(n<0||n>100_000_000_000L)throw new IllegalArgumentException("Неверная сумма начисления");}
    private final CompletableFuture<Void> stopped=new CompletableFuture<>();
    private final Consumer<Throwable> failure;private final CompletableFuture<Void> ready;
    @FunctionalInterface interface Sql<T>{T run()throws Exception;}
    public CompanyPayrollStore(Path file,Consumer<Throwable> failure){this.failure=failure;worker=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(512),r->{Thread t=new Thread(r,"NeverLand-Company-Payroll");t.setDaemon(true);return t;}){@Override protected void terminated(){try{if(db!=null)db.close();stopped.complete(null);}catch(SQLException ex){stopped.completeExceptionally(ex);failure.accept(ex);}}};ready=submit(()->{Files.createDirectories(file.toAbsolutePath().getParent());Class.forName("org.sqlite.JDBC");db=DriverManager.getConnection("jdbc:sqlite:"+file.toAbsolutePath());try(var s=db.createStatement()){s.execute("PRAGMA journal_mode=WAL");s.execute("PRAGMA synchronous=FULL");s.execute("PRAGMA busy_timeout=3000");try(var v=s.executeQuery("PRAGMA user_version")){if(v.next()&&v.getInt(1)>1)throw new SQLException("Неизвестная версия зарплат");}s.execute("PRAGMA user_version=1");s.execute("CREATE TABLE IF NOT EXISTS payroll_settings(company TEXT PRIMARY KEY,enabled INTEGER NOT NULL,budget INTEGER NOT NULL,rates TEXT NOT NULL,revision INTEGER NOT NULL)");s.execute("CREATE TABLE IF NOT EXISTS payroll_work(id TEXT PRIMARY KEY,company TEXT NOT NULL,employee TEXT NOT NULL,profession TEXT NOT NULL,level INTEGER NOT NULL,cents INTEGER NOT NULL,created INTEGER NOT NULL,state TEXT NOT NULL)");s.execute("CREATE INDEX IF NOT EXISTS payroll_budget ON payroll_work(company,created)");}refresh();healthy=true;return null;});}
    public CompletionStage<Void> stopped(){return stopped;}public CompletionStage<Void> ready(){return ready;}public boolean healthy(){return healthy&&!closed;}public Settings settings(UUID company){return settings.getOrDefault(company,Settings.empty(company));}public List<Work> outstanding(){return outstanding;}
    private <T> CompletableFuture<T> submit(Sql<T> work){var result=new CompletableFuture<T>();if(closed){result.completeExceptionally(new IllegalStateException("Зарплаты остановлены"));return result;}try{worker.execute(()->{try{result.complete(work.run());}catch(Throwable ex){if(!(ex instanceof IllegalArgumentException)){healthy=false;failure.accept(ex);}result.completeExceptionally(ex);}});}catch(RejectedExecutionException ex){healthy=false;failure.accept(ex);result.completeExceptionally(ex);}return result;}
    private void refresh()throws SQLException{var configs=new HashMap<UUID,Settings>();try(var s=db.createStatement();var r=s.executeQuery("SELECT * FROM payroll_settings")){while(r.next()){UUID id=UUID.fromString(r.getString(1));var rates=new HashMap<String,Long>();String raw=r.getString(4);if(!raw.isEmpty())for(String line:raw.split(",")){String[] pair=line.split("=",2);rates.put(pair[0],Long.parseLong(pair[1]));}configs.put(id,new Settings(id,r.getInt(2)!=0,r.getLong(3),rates,r.getLong(5)));}}var pending=new ArrayList<Work>();try(var s=db.createStatement();var r=s.executeQuery("SELECT * FROM payroll_work WHERE state IN ('OFFERED','REVIEW') ORDER BY created,id")){while(r.next()){pending.add(read(r));if(pending.size()>100_000)throw new SQLException("Очередь начислений переполнена; требуется сверка");}}settings=Map.copyOf(configs);outstanding=List.copyOf(pending);}
    private Work read(ResultSet r)throws SQLException{long cents=r.getLong("cents");money(cents);if(cents==0)throw new SQLException("Повреждено начисление");return new Work(UUID.fromString(r.getString("id")),UUID.fromString(r.getString("company")),UUID.fromString(r.getString("employee")),r.getString("profession"),r.getInt("level"),cents,r.getLong("created"),r.getString("state"));}
    public CompletionStage<Void> configure(Settings next,long expected){return submit(()->{Settings old=settings(next.company());if(old.revision()!=expected||next.revision()!=expected+1)throw new IllegalArgumentException("Условия зарплаты изменились. Повторите настройку");String rates=next.rates().entrySet().stream().sorted(Map.Entry.comparingByKey()).map(e->e.getKey()+"="+e.getValue()).collect(java.util.stream.Collectors.joining(","));try(var p=db.prepareStatement("INSERT OR REPLACE INTO payroll_settings VALUES(?,?,?,?,?)")){p.setString(1,next.company().toString());p.setInt(2,next.enabled()?1:0);p.setLong(3,next.budget());p.setString(4,rates);p.setLong(5,next.revision());p.executeUpdate();}refresh();return null;});}
    public CompletionStage<Boolean> offer(UUID id,UUID company,UUID employee,String profession,int level,long now,List<Double> multipliers){return submit(()->{
        if(!PROFESSIONS.contains(profession)||level<1||level>5)throw new IllegalArgumentException("Неизвестная профессия или уровень");
        try(var p=db.prepareStatement("SELECT 1 FROM payroll_work WHERE id=?")){p.setString(1,id.toString());try(var r=p.executeQuery()){if(r.next())return false;}}
        Settings cfg=settings(company);if(!cfg.enabled()||cfg.budget()==0)return false;long base=cfg.rates().getOrDefault(profession,0L);if(base==0)return false;long amount=java.math.BigDecimal.valueOf(base).multiply(java.math.BigDecimal.valueOf(multipliers.get(level-1))).setScale(0,java.math.RoundingMode.HALF_UP).longValueExact();money(amount);
        long used;try(var p=db.prepareStatement("SELECT coalesce(sum(cents),0) FROM payroll_work WHERE company=? AND created>? AND state<>'REJECTED'")){p.setString(1,company.toString());p.setLong(2,now-86_400_000L);try(var r=p.executeQuery()){r.next();used=r.getLong(1);}}
        if(amount==0||amount>cfg.budget()-used)return false;
        try(var p=db.prepareStatement("INSERT INTO payroll_work VALUES(?,?,?,?,?,?,?,?)")){p.setString(1,id.toString());p.setString(2,company.toString());p.setString(3,employee.toString());p.setString(4,profession);p.setInt(5,level);p.setLong(6,amount);p.setLong(7,now);p.setString(8,"OFFERED");p.executeUpdate();}refresh();return true;
    });}
    public CompletionStage<Void> state(UUID id,String state){if(!Set.of("DONE","REJECTED","REVIEW").contains(state))throw new IllegalArgumentException();return submit(()->{try(var p=db.prepareStatement("UPDATE payroll_work SET state=? WHERE id=? AND state IN ('OFFERED','REVIEW')")){p.setString(1,state);p.setString(2,id.toString());p.executeUpdate();}refresh();return null;});}
    public CompletionStage<List<Work>> history(UUID company){return submit(()->{var list=new ArrayList<Work>();try(var p=db.prepareStatement("SELECT * FROM payroll_work WHERE company=? ORDER BY created DESC,id LIMIT 45")){p.setString(1,company.toString());try(var r=p.executeQuery()){while(r.next())list.add(read(r));}}return List.copyOf(list);});}
    @Override public void close(){closed=true;healthy=false;worker.shutdown();}
}
